// Keep the last KEEP_DAYS days; everything older goes.
// Capped per run so a backlog drains over several nights instead of landing
// thousands of writes on SQLite at once - the deletes contend with the same
// file a booking writes to.
const KEEP_DAYS = 3;
const MAX_PER_RUN = 800;

const cutoff = Date.now() - KEEP_DAYS * 24 * 60 * 60 * 1000;
const seen = {};
const out = [];

// The List node paginates, so input arrives either as one item per page (each
// carrying a `data` array) or as one item per execution, depending on how n8n
// splits the response. Handle both rather than assuming.
for (const item of $input.all()) {
  const j = (item && item.json) || {};
  const rows = Array.isArray(j.data) ? j.data : [j];
  for (const e of rows) {
    if (!e || !e.id || seen[e.id]) continue;
    const started = Date.parse(e.startedAt || e.createdAt || '');
    if (!started || started >= cutoff) continue;
    seen[e.id] = 1;
    out.push({ json: { id: e.id, startedAt: e.startedAt } });
    if (out.length >= MAX_PER_RUN) return out;
  }
}
return out;

const items = $input.all();
const ok = items.filter(i => !(i.json && i.json.error)).length;
return [{ json: { pruned: ok, attempted: items.length, at: new Date().toISOString() } }];

